#!/usr/bin/env bun

// This script generates helper files for the Alumnium single-file executable.

import fs from "node:fs/promises";
import { createRequire } from "node:module";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { loadAgentPrompts } from "../../packages/typescript/core/src/server/agents/prompts/prompts.ts";
import { computeCursorSdkManifest } from "../../packages/typescript/cursor/src/standalone/cursorSdkManifest.ts";

const curName = fileURLToPath(import.meta.url);
const curDir = path.dirname(curName);

const bundles = await Promise.all([
  bundleDriverScripts(),
  bundleSeleniumScripts(),
  bundleAgentPrompts(),
  bundleCursorSdkManifest(),
]);

// NOTE: We write paths to stdout to use as oxfmt args
const bundlePaths = bundles
  .map((bundlePath) => JSON.stringify(bundlePath))
  .join(" ");
console.write(bundlePaths);

async function bundleDriverScripts() {
  const scriptsDir = path.resolve(
    curDir,
    "../../packages/typescript/core/src/drivers/scripts",
  );

  const waiterSource = await fs.readFile(
    path.resolve(scriptsDir, "waiter.js"),
    "utf-8",
  );
  const sliderSource = await fs.readFile(
    path.resolve(scriptsDir, "slider.js"),
    "utf-8",
  );

  const bundlePath = path.resolve(scriptsDir, "bundledScripts.ts");
  await fs.writeFile(
    bundlePath,
    `// This file is auto-generated by scripts/build/generate-bundles.ts. Do not edit it directly.

export const waiterScriptSource = ${JSON.stringify(waiterSource)};

export const sliderScriptSource = ${JSON.stringify(sliderSource)};
`,
  );
  return bundlePath;
}

async function bundleSeleniumScripts() {
  const seleniumDir = path.resolve(
    curDir,
    "../../packages/typescript/selenium",
  );
  const scriptsDir = path.resolve(seleniumDir, "src/drivers/scripts");
  const pythonScriptsDir = path.resolve(
    curDir,
    "../../packages/python/src/alumnium/drivers/scripts",
  );
  const require = createRequire(path.resolve(seleniumDir, "package.json"));
  const acquiescenceDir = path.dirname(
    require.resolve("acquiescence/package.json"),
  );
  const acquiescenceSource = await fs.readFile(
    path.resolve(acquiescenceDir, "dist/acquiescence.browser.js"),
    "utf-8",
  );
  // The formatter ends the function expression with a semicolon, which would
  // break drivers that call it as a function declaration.
  const ariaSnapshotSource = (
    await fs.readFile(path.resolve(scriptsDir, "ariaSnapshot.js"), "utf-8")
  ).replace(/;\s*$/, "\n");

  const bundlePath = path.resolve(scriptsDir, "bundledScripts.ts");
  await fs.writeFile(
    bundlePath,
    `// This file is auto-generated by scripts/build/generate-bundles.ts. Do not edit it directly.

// Bundles https://github.com/jimevans/acquiescence, licensed under Apache-2.0.
export const acquiescenceScriptSource = ${JSON.stringify(acquiescenceSource)};

export const ariaSnapshotScriptSource = ${JSON.stringify(ariaSnapshotSource)};
`,
  );

  // Python ships driver scripts as files, which Java copies from there.
  const header =
    "// This file is auto-generated by scripts/build/generate-bundles.ts. Do not edit it directly.\n";
  await fs.writeFile(
    path.resolve(pythonScriptsDir, "acquiescence.js"),
    `${header}// Bundles https://github.com/jimevans/acquiescence, licensed under Apache-2.0.

${acquiescenceSource.replace(/\n\/\/# sourceMappingURL=.*\n?$/, "\n")}`,
  );
  await fs.writeFile(
    path.resolve(pythonScriptsDir, "ariaSnapshot.js"),
    `${header}${ariaSnapshotSource}`,
  );

  return bundlePath;
}

async function bundleCursorSdkManifest() {
  const lockPath = path.resolve(curDir, "../../bun.lock");
  const lockText = await fs.readFile(lockPath, "utf-8");
  // bun.lock is JSONC; the only non-JSON syntax it uses is trailing commas,
  // and no value in it can contain ",}" / ",]" sequences.
  const lock = JSON.parse(lockText.replace(/,(\s*[}\]])/g, "$1"));

  const manifest = computeCursorSdkManifest(lock);

  const bundlePath = path.resolve(
    curDir,
    "../../packages/typescript/cursor/src/standalone/cursorSdkVendorManifest.ts",
  );
  await fs.writeFile(
    bundlePath,
    `// This file is auto-generated by scripts/build/generate-bundles.ts. Do not edit it directly.

import type { CursorSdkVendorManifest } from "./cursorSdkManifest.ts";

export const cursorSdkVendorManifest : CursorSdkVendorManifest = ${JSON.stringify(manifest, null, 2)};
`,
  );
  return bundlePath;
}

async function bundleAgentPrompts() {
  const prompts = await loadAgentPrompts();

  const bundlePath = path.resolve(
    curDir,
    "../../packages/typescript/core/src/server/agents/prompts/bundledPrompts.ts",
  );
  await fs.writeFile(
    bundlePath,
    `// This file is auto-generated by scripts/build/generate-bundles.ts. Do not edit it directly.

import type { AgentPrompts } from "./prompts.ts";

export const agentPrompts : AgentPrompts = ${JSON.stringify(prompts, null, 2)};
`,
  );
  return bundlePath;
}
